import re
from dataclasses import dataclass

class GecersizGirdi(ValueError):
    pass

@dataclass(frozen=True)
class BelgeId:
    """Sinir nesnesi: var olmasi, dogrulanmis olmasi demektir."""
    deger: str
    KALIP = re.compile(r"[0-9a-f]{8}")

    @classmethod
    def ayristir(cls, ham):
        if not isinstance(ham, str):
            raise GecersizGirdi("tur: %s" % type(ham).__name__)
        s = ham.strip().lower()
        if not cls.KALIP.fullmatch(s):
            raise GecersizGirdi("kalip")
        return cls(s)

def indir(bid):
    # Burada hic dogrulama yok; tur zaten garanti veriyor.
    assert isinstance(bid, BelgeId)
    return "depo/%s.pdf" % bid.deger

