class Tampon:
    """C'deki sabit boyutlu diziyi taklit eder; fark: her yazma sinir denetimli."""
    def __init__(self, boyut):
        self.boyut = boyut
        self.bayt = bytearray(boyut)

    def yaz(self, ofset, veri):
        if ofset < 0 or ofset + len(veri) > self.boyut:
            raise IndexError("sinir asimi: ofset=%d uzunluk=%d kapasite=%d"
                             % (ofset, len(veri), self.boyut))
        self.bayt[ofset:ofset + len(veri)] = veri
        return len(veri)

def guvenli_kopya(kapasite, kaynak):
    """snprintf mantigi: en cok kapasite-1 bayt kopyala, sonlandiriciyi daima koy."""
    if kapasite <= 0:
        raise ValueError("kapasite > 0 olmali")
    ham = kaynak.encode("utf-8")
    kesildi = len(ham) > kapasite - 1
    govde = ham[:kapasite - 1]
    return govde + b"\x00", kesildi

