INT32_MIN, INT32_MAX = -2**31, 2**31 - 1
SIZE_MAX32 = 2**32 - 1

class AritmetikTasmasi(ArithmeticError):
    pass

def guvenli_topla(a, b):
    t = a + b                                   # Python sarmaz; biz sinir koyuyoruz
    if not (INT32_MIN <= t <= INT32_MAX):
        raise AritmetikTasmasi("int32 tasmasi: %d + %d = %d" % (a, b, t))
    return t

def guvenli_carp(n, boyut):
    if n < 0 or boyut <= 0:
        raise ValueError("negatif sayim/boyut")
    if n > SIZE_MAX32 // boyut:                 # BOLME ile on denetim: carpmadan once
        raise AritmetikTasmasi("ayirma boyutu tasiyor: %d * %d" % (n, boyut))
    return n * boyut

