import json

MAX_DERINLIK = 3
SEMA = {
    "ad":      {"tur": str,  "en_cok": 64},
    "sayfa":   {"tur": int,  "min": 1, "max": 500},
    "gizli":   {"tur": bool},
}

class SemaHatasi(ValueError):
    pass

def derinlik(x, d=1):
    if isinstance(x, dict):
        return max([derinlik(v, d + 1) for v in x.values()] or [d])
    if isinstance(x, list):
        return max([derinlik(v, d + 1) for v in x] or [d])
    return d

def dogrula(metin):
    if len(metin) > 4096:
        raise SemaHatasi("govde cok buyuk: %d bayt" % len(metin))
    veri = json.loads(metin)
    if not isinstance(veri, dict):
        raise SemaHatasi("kok nesne olmali")
    d = derinlik(veri)
    if d > MAX_DERINLIK:
        raise SemaHatasi("derinlik %d > %d" % (d, MAX_DERINLIK))
    fazla = sorted(set(veri) - set(SEMA))
    if fazla:
        raise SemaHatasi("izin listesinde olmayan alan: %s" % fazla)
    for alan, kural in SEMA.items():
        if alan not in veri:
            raise SemaHatasi("eksik alan: %s" % alan)
        v = veri[alan]
        if type(v) is not kural["tur"]:
            raise SemaHatasi("%s turu %s olmali, %s geldi" % (alan, kural["tur"].__name__, type(v).__name__))
        if "en_cok" in kural and len(v) > kural["en_cok"]:
            raise SemaHatasi("%s cok uzun" % alan)
        if "min" in kural and not (kural["min"] <= v <= kural["max"]):
            raise SemaHatasi("%s araligi disinda: %r" % (alan, v))
    return veri

