import math

AV = {"N": 0.85, "A": 0.62, "L": 0.55, "P": 0.2}
AC = {"L": 0.77, "H": 0.44}
UI = {"N": 0.85, "R": 0.62}
CIA = {"H": 0.56, "L": 0.22, "N": 0.0}
PR_U = {"N": 0.85, "L": 0.62, "H": 0.27}
PR_C = {"N": 0.85, "L": 0.68, "H": 0.50}

def yukari_yuvarla(x):
    """CVSS 3.1 Roundup: bir ondalik basamaga YUKARI yuvarlar."""
    tam = int(x * 100000)
    if tam % 10000 == 0:
        return tam / 100000.0
    return (math.floor(tam / 10000) + 1) / 10.0

def taban_puan(av, ac, pr, ui, s, c, i, a):
    iss = 1 - (1 - CIA[c]) * (1 - CIA[i]) * (1 - CIA[a])
    if s == "U":
        etki = 6.42 * iss
        prd = PR_U[pr]
    else:
        etki = 7.52 * (iss - 0.029) - 3.25 * (iss - 0.02) ** 15
        prd = PR_C[pr]
    somurulebilirlik = 8.22 * AV[av] * AC[ac] * prd * UI[ui]
    if etki <= 0:
        return 0.0
    ham = min(etki + somurulebilirlik, 10.0) if s == "U" else min(1.08 * (etki + somurulebilirlik), 10.0)
    return yukari_yuvarla(ham), etki, somurulebilirlik

