class YetkiYok(PermissionError):
    pass

class Yetenek:
    """Yetenek = (kaynak, izinli eylemler). Tasiyan kullanir; baskasina verilebilir
    ama GENISLETILEMEZ: daraltma var, genisletme yok."""
    def __init__(self, kaynak, eylemler):
        self._kaynak = kaynak
        self._eylemler = frozenset(eylemler)

    def daralt(self, eylemler):
        yeni = self._eylemler & frozenset(eylemler)
        return Yetenek(self._kaynak, yeni)

    def kullan(self, eylem, veri=None):
        if eylem not in self._eylemler:
            raise YetkiYok("%s uzerinde '%s' yetkisi yok (izinli: %s)"
                           % (self._kaynak, eylem, sorted(self._eylemler)))
        return "%s:%s%s" % (self._kaynak, eylem, "" if veri is None else "(" + veri + ")")

    def __repr__(self):
        return "Yetenek(%s, %s)" % (self._kaynak, sorted(self._eylemler))

def donusturucu(giris, cikis):
    """Yalnizca iki yetenek alir: girisi oku, cikisa yaz. Baska hicbir seye erisemez."""
    ham = giris.kullan("oku")
    return cikis.kullan("yaz", "kucuk-" + ham.split(":")[0])

